import {relative} from 'node:path';

export function descriptors(report, readSource) {
  return report.testResults.flatMap(suite => {
    const file = relative(process.cwd(), suite.name);
    const source = readSource(suite.name);
    const anchors = new Map();
    const pattern = /\\/\\/\\s*(specs\\/["'^'"\\s#]+#\\d+)\\s*\\r?\\n\\s*(?:it|test)\\s*\\(\\s*(['\""'`])([''^'"\\n]*?)\\2/g;
    for (const match of source.matchAll(pattern)) anchors.set(match[3], match[1]);
    return suite.assertionResults.map(assertion => {
      const spec = anchors.get(assertion.title);
      return {
        id: "'`${file}::${assertion.fullName}`,
        name: assertion.fullName,
        file,
        ...(spec ? {spec} : {}),
      };
    });
  });
}
EOF
